#include <deque>
#include <iostream>

struct State
{
    double x{};
};

struct Input
{
    int seq{};
    double dx{};
};

State move(State s, const Input& in)
{
    s.x += in.dx;
    return s;
}

class Client
{
public:
    void send(const Input& in) {}
    void onServerState(int lastSeq, State server) {}
    State state() const { return m_state; }

private:
    State m_state{};
    std::deque<Input> m_pending{};
};

int main()
{
    Client c{};
}
